import{M as i}from"./chunk-I35EDW7W.js";var o=[{id:"p5-1",sentenceWithBlank:"The manager ____ the meeting every Monday morning.",options:["hold","holds","holding","held"],correctIndex:1,explanationVi:'Ch\u1EE7 ng\u1EEF s\u1ED1 \xEDt "The manager" \u1EDF th\xEC hi\u1EC7n t\u1EA1i \u0111\u01A1n c\u1EA7n \u0111\u1ED9ng t\u1EEB th\xEAm "s": holds.'},{id:"p5-2",sentenceWithBlank:"Our sales figures were much ____ than expected last quarter.",options:["high","higher","highest","more high"],correctIndex:1,explanationVi:'So s\xE1nh h\u01A1n v\u1EDBi t\xEDnh t\u1EEB ng\u1EAFn "high" \u2192 "higher" (th\xEAm -er).'},{id:"p5-3",sentenceWithBlank:"The new policy ____ by the board of directors last week.",options:["approved","was approved","approves","has approve"],correctIndex:1,explanationVi:'C\xE2u b\u1ECB \u0111\u1ED9ng \u1EDF th\xEC qu\xE1 kh\u1EE9 \u0111\u01A1n: was/were + V3. "The policy was approved."'},{id:"p5-4",sentenceWithBlank:"If the client ____ satisfied, we will offer a full refund.",options:["is not","was not","will not be","not be"],correctIndex:0,explanationVi:'C\xE2u \u0111i\u1EC1u ki\u1EC7n lo\u1EA1i 1: If + hi\u1EC7n t\u1EA1i \u0111\u01A1n, ... will + V. "If the client is not satisfied..."'},{id:"p5-5",sentenceWithBlank:"She told me that she ____ the report the day before.",options:["finishes","finished","had finished","will finish"],correctIndex:2,explanationVi:"C\xE2u t\u01B0\u1EDDng thu\u1EADt l\xF9i th\xEC: h\xE0nh \u0111\u1ED9ng x\u1EA3y ra tr\u01B0\u1EDBc m\u1ED9t m\u1ED1c qu\xE1 kh\u1EE9 d\xF9ng qu\xE1 kh\u1EE9 ho\xE0n th\xE0nh (had finished)."},{id:"p5-6",sentenceWithBlank:"Please submit your application ____ Friday.",options:["in","on","at","by"],correctIndex:3,explanationVi:'"By + th\u1EDDi gian" ngh\u0129a l\xE0 "tr\u01B0\u1EDBc ho\u1EB7c v\xE0o th\u1EDDi \u0111i\u1EC3m \u0111\xF3 (h\u1EA1n ch\xF3t)" \u2014 ph\xF9 h\u1EE3p ng\u1EEF c\u1EA3nh n\u1ED9p h\u1ED3 s\u01A1.'},{id:"p5-7",sentenceWithBlank:"The company has grown ____ over the past five years.",options:["significant","significance","significantly","more significant"],correctIndex:2,explanationVi:'B\u1ED5 ngh\u0129a cho \u0111\u1ED9ng t\u1EEB "grown" c\u1EA7n tr\u1EA1ng t\u1EEB: "significantly".'},{id:"p5-8",sentenceWithBlank:"Employees ____ arrive late must inform their supervisor.",options:["who","which","whose","whom"],correctIndex:0,explanationVi:'\u0110\u1EA1i t\u1EEB quan h\u1EC7 ch\u1EC9 ng\u01B0\u1EDDi l\xE0m ch\u1EE7 ng\u1EEF: "who".'},{id:"p5-9",sentenceWithBlank:"The conference room is ____ for meetings on the third floor.",options:["available","availability","avail","availably"],correctIndex:0,explanationVi:'Sau \u0111\u1ED9ng t\u1EEB "to be" c\u1EA7n t\xEDnh t\u1EEB: "available".'},{id:"p5-10",sentenceWithBlank:"By the time the guests arrive, we ____ the decorations.",options:["finish","will have finished","finished","are finishing"],correctIndex:1,explanationVi:'Th\xEC t\u01B0\u01A1ng lai ho\xE0n th\xE0nh di\u1EC5n t\u1EA3 vi\u1EC7c ho\xE0n t\u1EA5t tr\u01B0\u1EDBc m\u1ED9t m\u1ED1c trong t\u01B0\u01A1ng lai: "will have finished".'},{id:"p5-11",sentenceWithBlank:"This is the ____ efficient method we have tried so far.",options:["more","most","much","many"],correctIndex:1,explanationVi:'So s\xE1nh nh\u1EA5t v\u1EDBi t\xEDnh t\u1EEB d\xE0i: "the most efficient".'},{id:"p5-12",sentenceWithBlank:"The invoice ____ to the wrong address last month.",options:["sent","was sent","sends","is sending"],correctIndex:1,explanationVi:'C\xE2u b\u1ECB \u0111\u1ED9ng, th\xEC qu\xE1 kh\u1EE9 \u0111\u01A1n: "was sent".'},{id:"p5-13",sentenceWithBlank:"He asked me ____ I could help him with the project.",options:["that","if","what","so"],correctIndex:1,explanationVi:'C\xE2u h\u1ECFi Yes/No trong c\xE2u t\u01B0\u1EDDng thu\u1EADt d\xF9ng "if" ho\u1EB7c "whether".'},{id:"p5-14",sentenceWithBlank:"The department needs someone who is ____ in data analysis.",options:["skill","skilled","skillful","skillfully"],correctIndex:1,explanationVi:'"be skilled in something" l\xE0 c\u1EE5m t\xEDnh t\u1EEB \u0111\xFAng ngh\u0129a "c\xF3 k\u1EF9 n\u0103ng v\u1EC1".'},{id:"p5-15",sentenceWithBlank:"We ____ the new software for two months before the crash happened.",options:["use","used","had been using","have used"],correctIndex:2,explanationVi:'H\xE0nh \u0111\u1ED9ng k\xE9o d\xE0i tr\u01B0\u1EDBc m\u1ED9t m\u1ED1c trong qu\xE1 kh\u1EE9 d\xF9ng qu\xE1 kh\u1EE9 ho\xE0n th\xE0nh ti\u1EBFp di\u1EC5n: "had been using".'},{id:"p5-16",sentenceWithBlank:"Neither the manager ____ the staff were informed about the change.",options:["or","nor","but","and"],correctIndex:1,explanationVi:'C\u1EA5u tr\xFAc "neither...nor..." (kh\xF4ng...c\u0169ng kh\xF4ng...).'},{id:"p5-17",sentenceWithBlank:"The results of the survey were ____ than we had hoped.",options:["disappointing","more disappointing","most disappointing","disappoint"],correctIndex:1,explanationVi:'So s\xE1nh h\u01A1n v\u1EDBi t\xEDnh t\u1EEB d\xE0i: "more disappointing than".'},{id:"p5-18",sentenceWithBlank:"The contract will not be signed ____ both parties agree to the terms.",options:["unless","if","because","although"],correctIndex:0,explanationVi:'"unless" ngh\u0129a l\xE0 "tr\u1EEB khi", ph\xF9 h\u1EE3p v\u1EDBi \xFD "s\u1EBD kh\xF4ng k\xFD tr\u1EEB khi c\u1EA3 hai b\xEAn \u0111\u1ED3ng \xFD".'},{id:"p5-19",sentenceWithBlank:"All visitors are required ____ an ID badge at all times.",options:["wear","wearing","to wear","wore"],correctIndex:2,explanationVi:'C\u1EA5u tr\xFAc "be required to + V-infinitive": "are required to wear".'},{id:"p5-20",sentenceWithBlank:"The email you sent yesterday ____ still under review.",options:["is","are","was","were"],correctIndex:0,explanationVi:'Ch\u1EE7 ng\u1EEF "The email" s\u1ED1 \xEDt, hi\u1EC7n t\u1EA1i \u0111\u01A1n d\xF9ng "is".'}];var a=[{id:"reading-email",titleVi:"Email n\u1ED9i b\u1ED9 c\xF4ng ty",passageEn:`Subject: Office Renovation Notice

Dear Staff,

Please be informed that the third floor of our office will be closed for renovation from June 10 to June 20. During this period, all employees who normally work on the third floor should move to the meeting rooms on the second floor. The IT department will help set up temporary desks and internet connections on June 9. If you have any questions, please contact the facilities team at ext. 245.

Thank you for your understanding.

Best regards,
Facilities Department`,questions:[{id:"reading-email-q1",question:"Why is the third floor being closed?",options:["For a company party","For renovation","For a fire drill","For a client visit"],correctIndex:1},{id:"reading-email-q2",question:"Where should third-floor employees work during the closure?",options:["At home","On the second floor","On the fourth floor","In the parking lot"],correctIndex:1},{id:"reading-email-q3",question:"Who should employees contact with questions?",options:["The IT department","The facilities team","Human resources","The manager"],correctIndex:1}]},{id:"reading-advertisement",titleVi:"Qu\u1EA3ng c\xE1o tuy\u1EC3n d\u1EE5ng",passageEn:"Bright Future Language Center is looking for a part-time English teacher for weekend classes. Applicants should have at least one year of teaching experience and be comfortable working with students aged 10 to 15. Classes are held on Saturdays and Sundays from 9:00 a.m. to 12:00 p.m. Interested candidates should send their resume to careers@brightfuture.example before July 5.",questions:[{id:"reading-ad-q1",question:"What position is being advertised?",options:["A full-time manager","A part-time English teacher","A school director","An IT support staff"],correctIndex:1},{id:"reading-ad-q2",question:"When are the classes held?",options:["On weekdays","On Saturdays and Sundays","Every evening","Once a month"],correctIndex:1},{id:"reading-ad-q3",question:"How should applicants apply?",options:["Call the center","Visit in person","Send a resume by email","Send a text message"],correctIndex:2}]},{id:"reading-notice",titleVi:"Th\xF4ng b\xE1o c\u1EEDa h\xE0ng",passageEn:`Notice to Customers

Greenway Supermarket will be open for extended hours during the holiday season, from December 20 to January 2. The store will open at 7:00 a.m. and close at 11:00 p.m. every day, including weekends. Please note that the customer service desk will close one hour earlier than the store. We wish all our customers a happy holiday season!`,questions:[{id:"reading-notice-q1",question:"What is the notice mainly about?",options:["A price increase","Extended holiday store hours","A store closing permanently","A new product launch"],correctIndex:1},{id:"reading-notice-q2",question:"What time does the customer service desk close?",options:["7:00 a.m.","10:00 p.m.","11:00 p.m.","12:00 a.m."],correctIndex:1}]}];var s=o,r=a;var h=class e{part5Questions=s;readingPassages=r;getReadingPassage(t){return this.readingPassages.find(n=>n.id===t)}static \u0275fac=function(n){return new(n||e)};static \u0275prov=i({token:e,factory:e.\u0275fac,providedIn:"root"})};export{h as a};
